function persist(){
  if(viewer)return Promise.resolve();
  const copy=structuredClone(library);
  saveQueue=saveQueue.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{if(!db)return reject(Error('Local saving is unavailable. Export a backup before closing.'));const tx=db.transaction('library','readwrite');tx.objectStore('library').put(copy,'main');tx.oncomplete=resolve;tx.onerror=()=>reject(Error('Local saving failed. Export a backup before closing.'));}));
  saveQueue.catch(fail);return saveQueue;
}
