  $$('[data-room]').forEach(b=>b.onclick=()=>switchProject(b.dataset.room));act('#new-room',()=>projectDialog());act('#sidebar-home',()=>navigate(null));
  $('#language').value=language();$('#language').onchange=async e=>{p.language=e.target.value;await persist();navigate(activeTrack);};
