async function moveLibrary(id,target){const a=library.projects.findIndex(p=>p.id===id),b=library.projects.findIndex(p=>p.id===target);if(a<0||b<0||a===b)return;const [p]=library.projects.splice(a,1);library.projects.splice(b,0,p);await persist();navigate(activeTrack);}
function folders(p){return [...new Set([...(p.folders||[]),...p.tracks.map(t=>t.collection).filter(Boolean)])].sort();}
function visibility(t){return ['visible','hidden','locked'].includes(t.visibility)?t.visibility:(t.status==='archived'?'hidden':'visible');}
