function editFolder(old){const p=project();dialog('Edit folder',`${field('Folder name','folder-edit-name',old,'required maxlength="100"')}<div class="field"><label for="folder-edit-colour">Colour</label><input type="color" id="folder-edit-colour" value="${folderColor(old)}"></div>`,'<button type="button" id="remove-folder" class="danger">Remove folder</button><button value="cancel">Cancel</button><button type="submit" id="save-folder" class="primary">Save</button>',()=>{act('#remove-folder',async()=>{p.tracks.forEach(t=>{if(t.collection===old)t.collection='';});p.folders=(p.folders||[]).filter(f=>f!==old);delete p.folderColors?.[old];collection='all';await persist();$('#dialog').close();renderLibrary();});$('#dialog-form').onsubmit=async e=>{if(e.submitter?.id!=='save-folder')return;e.preventDefault();const name=$('#folder-edit-name').value.trim();if(!name)return;p.tracks.forEach(t=>{if(t.collection===old)t.collection=name;});p.folders=[...new Set((p.folders||[]).map(f=>f===old?name:f))];p.folderColors||={};delete p.folderColors[old];p.folderColors[name]=$('#folder-edit-colour').value;if(collection===old)collection=name;await persist();$('#dialog').close();renderLibrary();};});}

