  $$('[data-tag]').forEach(b=>b.onclick=()=>{$('#search').value=search=search===b.dataset.tag?'':b.dataset.tag;renderRows();});
  act('#import',()=>$('#file-input').click());act('#project-backup',()=>saveBackup(false));act('#trash',trashDialog);folderNavigation();renderRows();translate($('#content'),language());
