    const real=staves.filter(Boolean);if(!real.length)return;const scale=10*osmd.Zoom,boxes=real.map(m=>m.PositionAndShape),x=Math.min(...boxes.map(b=>b.AbsolutePosition.x)),y=Math.min(...boxes.map(b=>b.AbsolutePosition.y+b.BorderTop)),right=Math.max(...boxes.map(b=>b.AbsolutePosition.x+b.Size.width)),bottom=Math.max(...boxes.map(b=>b.AbsolutePosition.y+b.BorderBottom));
