      const key=t.lockMode==='piece'?t.id:p.id;
      if(!passwords.has(key)){const pw=await passwordPrompt(t.lockMode==='piece'?`Password for ${t.title}`:`Shared password for ${p.name}`,true);if(pw===null)throw Error('Export cancelled.');passwords.set(key,pw);}
